# frozen_string_literal: true

# Generated by Descant: acceptance tests.

require "rails_helper"
require_relative "../../contracts/timekeeping/prepare_reconciliation_examples"

RSpec.describe Invoices::SaveReconciliation do
  # "remote committed with intent committed → existing_success; remote aborted with intent failed → save_failed; any other pair → retryable reconciliation_error."
  it "settles only the committed-committed and aborted-failed pairs and retries every crossed pair" do
    expect(described_class.call(remote_state: "committed", intent_state: "committed"))
      .to eq("outcome" => "existing_success", "retryable" => false, "changed" => false)
    expect(described_class.call(remote_state: "aborted", intent_state: "failed"))
      .to eq("outcome" => "save_failed", "retryable" => false, "changed" => false)

    retry_answer = { "outcome" => "reconciliation_error", "retryable" => true, "changed" => false }
    [%w[committed failed], %w[aborted committed], %w[committed pending], %w[prepared committed]].each do |remote, intent|
      expect([remote, intent, described_class.call(remote_state: remote, intent_state: intent)])
        .to eq([remote, intent, retry_answer])
    end
  end
end

RSpec.describe Invoices::SaveReconciliation, "against the contract's shared examples" do
  let(:reconciler) { described_class }
  let(:fallback) { { "outcome" => "reconciliation_error", "retryable" => true, "changed" => false } }

  it_behaves_like "timekeeping prepare reconciliation"

  it "retries a remote prepared state whatever the intent state" do
    %w[pending committed failed].each do |intent_state|
      expect([intent_state, described_class.call(remote_state: "prepared", intent_state:)]).to eq([intent_state, fallback])
    end
  end

  it "takes the fallback when no remote state was established" do
    expect(described_class.call(remote_state: nil, intent_state: "committed")).to eq(fallback)
    expect(described_class.call(remote_state: nil, intent_state: nil)).to eq(fallback)
  end
end
